  function transitionLabel(id){const b=BUILTIN_TRANSITIONS.find(x=>x[0]===id);if(b)return b[1];return GL_CATALOG.find(x=>x.id===id)?.label||id}
  function shortTransition(id){return transitionLabel(id).replace('씬 전환 · ','').slice(0,12)}
  function stopPreviewLoops(){for(const stop of previewLoops)try{stop()}catch{}previewLoops.clear()}
  async function previewTransitionOnMain(id){const s=selectedScene();if(!s)return;s.transition=id;renderInspector();play()}

  async function renderStaticPreview(time=null){if(playing||destroyed)return;const s=selectedScene(),idx=s?Math.max(0,project.scenes.indexOf(s)):0,t=s?(time??Math.min(.8,s.duration*.45)):0;try{const c=await renderGifFrame(project,idx,t,0,520);ctx.clearRect(0,0,520,520);ctx.drawImage(c,0,0);setPreviewStatus(s?'🟢 미리보기 정상':'🟢 배경 미리보기')}catch(e){console.warn(e);ctx.clearRect(0,0,520,520);ctx.fillStyle='#211f28';ctx.fillRect(0,0,520,520);ctx.fillStyle='#ffb9c9';ctx.font='700 16px sans-serif';ctx.textAlign='center';ctx.fillText('미디어 렌더링 실패',260,245);ctx.font='12px sans-serif';ctx.fillText(String(e.message||e),260,270);setPreviewStatus('🔴 렌더링 오류')}}
  function setPreviewStatus(text){const el=$('#previewStatus',root);if(el)el.textContent=text}
  function totalDuration(){return project.scenes.reduce((a,s)=>a+(s.duration||1.5),0)}
  function locateTime(t){let acc=0;for(let i=0;i<project.scenes.length;i++){const d=project.scenes[i].duration||1.5;if(t<acc+d)return{i,local:t-acc};acc+=d}return{i:Math.max(0,project.scenes.length-1),local:0}}
  function play(){if(!project.scenes.length){toast('먼저 Scene을 추가하세요.','error');return}playing=true;startTime=performance.now();cancelAnimationFrame(raf);tick()}
  function stop(){playing=false;cancelAnimationFrame(raf);renderStaticPreview()}
