  async function exportGif(){if(!project.scenes.length){toast('먼저 Scene을 추가하세요.','error');return}const btn=$('[data-act="exportGif"]',root),badge=$('#gif-size-badge',root);btn.disabled=true;try{const result=await exportOptimizedGif(project,{size:project.output.size,fps:project.output.fps,colors:project.output.colors,maxBytes:project.output.maxBytes,onProgress:(p,msg)=>{btn.textContent=`${Math.round(p*100)}% ${msg}`}});downloadBlob(result.blob,'profile-motion-v2.3.gif');badge.textContent=`완료 ${bytesText(result.bytes)} · ${result.size}px · ${result.fps}fps`;badge.className='size-badge ok';toast('GIF 저장 완료','success')}catch(e){badge.textContent='내보내기 실패';badge.className='size-badge bad';toast(e.message,'error')}finally{btn.disabled=false;btn.textContent='GIF ≤ 2MB 저장'}}
  function updateBadge(){const d=totalDuration(),estimated=project.output.size*project.output.size*project.output.fps*Math.max(.3,d)*(project.output.colors/256)*.16,badge=$('#gif-size-badge',root);badge.textContent=`예상 ${bytesText(estimated)} · ${project.output.size}px 🔒 · 제한 1.90MB`;badge.className=`size-badge ${estimated<project.output.maxBytes?'ok':'warn'}`}

  async function importFont(){const choice=prompt('폰트 불러오기\n1 = TTF/OTF/WOFF/WOFF2 파일\n2 = WOFF/WOFF2 URL\n3 = @font-face CSS','1');try{if(choice==='1'){const f=await filePicker('.ttf,.otf,.woff,.woff2,font/*');if(f)await fontRegistry.addFile(f)}else if(choice==='2'){const url=prompt('폰트 직접 URL');if(!url)return;const name=prompt('폰트 이름','Custom WebFont');await fontRegistry.addUrl(url,name)}else if(choice==='3'){const css=prompt('@font-face CSS를 붙여넣으세요. 폰트 라이선스와 CORS를 확인하세요.');if(css)await fontRegistry.addCss(css)}renderPanel();toast('폰트를 불러왔고 선택창에 등록했습니다.','success')}catch(e){toast(`폰트 로드 실패: ${e.message}`,'error')}}
  function showFonts(){const names=fontRegistry.list().map(x=>`${x.builtin?'•':'★'} ${x.name||x.family}`).join('\n');alert(`현재 선택 가능한 폰트\n\n${names}`)}

  function onKey(e){const tag=e.target?.tagName?.toLowerCase();if(['input','textarea','select'].includes(tag)&&!(e.ctrlKey||e.metaKey))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();const p=e.shiftKey?history.redo(project):history.undo(project);if(p)setProject(p)}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();const p=history.redo(project);if(p)setProject(p)}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProjectFile(project)}else if(e.code==='Space'){e.preventDefault();playing?stop():play()}}
  async function init(){bind();window.addEventListener('keydown',onKey);await fontRegistry.init();overlayAssets=await getAssets('overlay').catch(()=>[]);renderPanel();renderTimeline();renderInspector();renderStaticPreview();updateBadge();autosave()}
